import assert from "node:assert/strict";
import {
  chunkTextRanges,
  chunkMarkdownIR,
  markdownToIR,
  sliceMarkdownIR,
  renderMarkdownWithAttributedRanges,
} from "openclaw/plugin-sdk/text-chunking";

export default {
  id: "markdown-nan-proof",
  name: "Markdown NaN proof",
  register(api) {
    api.registerCli(({ program }) => {
      program.command("markdown-nan-proof").action(() => {
        const limit = Number.NaN;
        const ir = markdownToIR("**😀Hi** _é_");
        const ranges = chunkTextRanges(ir.text, { limit });
        const render = (chunk) => renderMarkdownWithAttributedRanges(chunk, {
          styleMap: { bold: "bold", italic: "italic" },
        });
        const rangePayloads = ranges.map(({ start, end }) =>
          render(sliceMarkdownIR(ir, start, end)));
        const irPayloads = chunkMarkdownIR(ir, limit).map(render);
        const validRanges = ranges.every(({ start, end }) =>
          Number.isInteger(start) && Number.isInteger(end) &&
          start >= 0 && end > start && end <= ir.text.length);
        const sdkResolvesToDist = import.meta.resolve(
          "openclaw/plugin-sdk/text-chunking").includes("/dist/");
        const output = {
          limitType: typeof limit,
          limitIsNaN: Number.isNaN(limit),
          sdkResolvesToDist,
          validRanges,
          ranges,
          rangePayloads,
          irPayloads,
        };
        process.stdout.write(JSON.stringify(output) + "\n");
        const expected = [{
          text: "😀Hi é",
          ranges: [
            { start: 0, length: 4, style: "bold" },
            { start: 5, length: 2, style: "italic" },
          ],
        }];
        assert.equal(output.limitType, "number");
        assert.equal(output.limitIsNaN, true);
        assert.equal(sdkResolvesToDist, true);
        assert.equal(validRanges, true);
        assert.deepEqual(ranges, [{ start: 0, end: 7 }]);
        assert.deepEqual(rangePayloads, expected);
        assert.deepEqual(irPayloads, expected);
        process.stdout.write("PASS: complete text and UTF-16 styles retained\n");
      });
    }, { descriptors: [{
      name: "markdown-nan-proof",
      description: "Check attributed payload retention with a NaN limit",
      hasSubcommands: false,
    }] });
  },
};
