  assert.equal(JSON.parse(control.stdout).valid, true);
  receipt.directoryControl = true;
  // Only the tarball is delivered; the recipient must not read the author's directory.
  await fs.rename(author, path.join(output, 'author-unavailable'));
  const inspect = await cli(['templates', 'inspect', artifact, '--json']);
  receipt.archiveInspectExit = inspect.status;
  await fs.writeFile(path.join(output, 'receipt.json'), JSON.stringify(receipt, null, 2));
  if (expectation === 'red') {
    assert.equal(inspect.status, 1, inspect.stderr + inspect.stdout);
    receipt.archiveInspectFailure = { stdout: inspect.stdout, stderr: inspect.stderr };
    receipt.status = 'PASS_RED';
  } else {
  assert.equal(inspect.status, 0, `archive inspection failed: ${inspect.stdout} ${inspect.stderr}`);
  const inspected = JSON.parse(inspect.stdout);
  assert.equal(inspected.valid, true);
  await assert.rejects(fs.stat(inspected.source.packageRoot), { code: 'ENOENT' });
  const originalHash = createHash('sha256').update(await fs.readFile(artifact)).digest('hex');
  receipt.artifact = { sha256: originalHash, bytes: (await fs.stat(artifact)).size,
    inspectTemporarySourceRemoved: true };
  const corrupt = path.join(output, 'corrupt.tgz');
  const corruptWorkspace = path.join(output, 'corrupt-workspace');
  await fs.writeFile(corrupt, 'invalid archive bytes');
  const deniedCorrupt = await cli(['templates', 'add', corrupt, '--workspace', corruptWorkspace, '--json']);
  assert.equal(deniedCorrupt.status, 1);
  assert.match(deniedCorrupt.stdout, /invalid_template_archive/);
  await assert.rejects(fs.stat(corruptWorkspace), { code: 'ENOENT' });
  const disabledWorkspace = path.join(output, 'disabled-workspace');
  await fs.writeFile(configPath, JSON.stringify({ ...allowedConfig,
    gateway: { controlUi: { experimental: { templates: false } } } }));
  const deniedLabs = await cli(['templates', 'add', artifact, '--workspace', disabledWorkspace, '--json']);
  assert.equal(deniedLabs.status, 1);
  assert.match(deniedLabs.stdout, /templates_labs_disabled/);
  await assert.rejects(fs.stat(disabledWorkspace), { code: 'ENOENT' });
  await fs.writeFile(configPath, JSON.stringify(allowedConfig));
  receipt.negativeControls = { corruptArchiveRejected: true, labsDisabledRejected: true,
    neitherCreatedWorkspace: true };
  const workspace = path.join(output, 'recipient-workspace');
  const preview = await cli(['templates', 'add', artifact, '--dry-run', '--workspace', workspace, '--json']);
  assert.equal(preview.status, 0, preview.stderr);
  assert.equal(JSON.parse(preview.stdout).blockers.length, 0);
  await assert.rejects(fs.stat(workspace), { code: 'ENOENT' });
  const add = await cli(['templates', 'add', artifact, '--workspace', workspace, '--json']);
  assert.equal(add.status, 0, `${add.stdout} ${add.stderr}`);
  const added = JSON.parse(add.stdout);
  assert.equal(added.status, 'complete');
  assert.match(await fs.readFile(path.join(workspace, 'SOUL.md'), 'utf8'), /orchard-lantern-42/);
  const list = await cli(['agents', 'list', '--json']);
  assert.equal(list.status, 0, list.stderr);
  assert.ok(JSON.parse(list.stdout).some((agent: { id: string }) => agent.id === added.agent.finalId));
  assert.equal(createHash('sha256').update(await fs.readFile(artifact)).digest('hex'), originalHash);
  await assert.rejects(fs.stat(added.template.packageRoot), { code: 'ENOENT' });
  receipt.recipient = { added: true, bodyReadback: true, freshProcessAgentReadback: true,
    authorUnavailable: true, previewDidNotCreateWorkspace: true,
    extractionRemovedAfterAdd: true, inputArchiveUnchanged: true };
  receipt.status = 'PASS_GREEN';
  }
} finally {
  await fs.writeFile(path.join(output, 'receipt.json'), JSON.stringify(receipt, null, 2));
  console.log(JSON.stringify(receipt, null, 2));
}

